-- Q08 · Of the patients first seen in a given month, how many come back 1, 2, 3... months later?
-- Techniques: cohort assignment with MIN() OVER, month offsets with date_diff,
--             retention matrix generated by a Jinja loop over COUNT(DISTINCT ...) FILTER.
with visits as (
    select distinct patient_id, admit_month
    from {{ ref('stg_encounters') }}
),
cohorts as (
    select
        patient_id,
        min(admit_month) over (partition by patient_id)                                  as cohort_month,
        date_diff('month', min(admit_month) over (partition by patient_id), admit_month) as months_since_first
    from visits
)
select
    strftime(cohort_month, '%Y-%m')  as cohort_month,
    count(distinct patient_id)       as cohort_size,
{%- for m in range(1, 7) %}
    {{ safe_pct('count(distinct patient_id) filter (where months_since_first = ' ~ m ~ ')',
                'count(distinct patient_id)') }} as m{{ m }}_pct,
{%- endfor %}
    {{ safe_pct('count(distinct patient_id) filter (where months_since_first between 1 and 6)',
                'count(distinct patient_id)') }} as any_return_6m_pct
from cohorts
group by cohort_month
order by cohort_month
